/* Qualia Lab: transparent deterministic toy models, not a theory of consciousness. */
(function(root){
'use strict';
const fields=['color','saturation','illumination','shadow','angle','shape','pitch','loudness','texture','temperature','taste','smell','context','association','emotion','previous'];
const groups={memory:[13,15],context:[12],senses:[6,7,8,9,10,11],shape:[5],emotion:[14]};
const labels=[['green','neutral','red'],['low tone','quiet','high tone'],['cool','neutral','warm'],['bitter','neutral','sweet'],['earthy','neutral','floral']];
function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
const clamp=x=>Math.max(-1,Math.min(1,x));
const zeros=n=>Array(n).fill(0);
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
const rms=(a,b)=>Math.sqrt(a.reduce((s,x,i)=>s+(x-b[i])**2,0)/a.length);
const clone=x=>JSON.parse(JSON.stringify(x));
function base(){return [.88,.8,.65,.12,0,-1,.2,.3,.1,.1,.4,.3,.2,.2,.1,0];}
function agent(){return{offset:0,memory:0,emotion:0,senses:1,gates:{memory:true,context:true,senses:true,shape:true,emotion:true},invert:false,compensate:true,labels:false};}
function effective(raw,a,ablate=[]){let x=raw.slice();x[12]=clamp(x[12]+a.offset);x[13]=clamp(x[13]+a.memory);x[14]=clamp(x[14]+a.emotion);for(let i=6;i<12;i++)x[i]*=a.senses;for(const [k,idx] of Object.entries(groups))if(!a.gates[k]||ablate.includes(k))for(const i of idx)x[i]=0;x[0]=clamp(x[0]*(.25+.75*x[1])*(.45+.55*x[2])*(1-.55*x[3])*(1-.15*Math.abs(x[4])));return x;}
function targets(x){const cat=v=>v>.22?2:v<-.22?0:1;return[cat(x[0]),x[7]<.12?1:(x[6]>0?2:0),cat(x[9]),cat(x[10]),cat(x[11]),(.5*x[14]+.25*x[13]+.15*x[12]+.1*x[10]>=0?1:0)];}
function sample(r,history=0){const x=Array.from({length:16},()=>r()*2-1);[1,2,3,7].forEach(i=>x[i]=r());x[5]=r()<.5?-1:1;if(history){x[12]=clamp(-.75*x[0]+.4*x[12]);x[13]=clamp(.7*x[6]+.4*x[13]);x[14]=clamp(-.6*x[10]+.5*x[14]);x[8]=clamp(-.7*x[5]+.4*x[8]);}return x;}
function makeNet(seed){const r=rng(seed),mat=(n,m,s)=>Array.from({length:n},()=>Array.from({length:m},()=>s*(r()*2-1)));return{w:mat(8,16,.35),b:zeros(8),v:mat(17,8,.3),c:zeros(17),d:mat(16,8,.25),e:zeros(16)};}
function probs(logits){const out=[];for(let g=0;g<6;g++){const start=g<5?g*3:15,n=g<5?3:2,l=logits.slice(start,start+n),mx=Math.max(...l),ex=l.map(v=>Math.exp(v-mx)),sum=ex.reduce((a,b)=>a+b,0);out.push(ex.map(v=>v/sum));}return out;}
function forward(net,x){const h=net.w.map((w,j)=>Math.tanh(dot(w,x)+net.b[j]));return{h,p:probs(net.v.map((v,k)=>dot(v,h)+net.c[k]))};}
function learn(net,x,ys,lr){const {h,p}=forward(net,x),delta=[];p.forEach((q,g)=>q.forEach((v,k)=>delta.push(v-(k===ys[g]?1:0))));const dh=zeros(8);for(let k=0;k<17;k++){for(let j=0;j<8;j++){dh[j]+=delta[k]*net.v[k][j];net.v[k][j]-=lr*delta[k]*h[j];}net.c[k]-=lr*delta[k];}for(let i=0;i<16;i++){const y=Math.tanh(dot(net.d[i],h)+net.e[i]),d=.2*(y-x[i])*(1-y*y);for(let j=0;j<8;j++){dh[j]+=d*net.d[i][j];net.d[i][j]-=lr*d*h[j];}net.e[i]-=lr*d;}for(let j=0;j<8;j++){const d=dh[j]*(1-h[j]*h[j]);for(let i=0;i<16;i++)net.w[j][i]-=lr*d*x[i];net.b[j]-=lr*d;}}
async function trainPair({seed=42,history='different',epochs=24,samples=700},progress=()=>{}){const a=makeNet(seed),b=makeNet(seed),rA=rng(seed+101),rB=rng(seed+101),aa=agent();const dataA=Array.from({length:samples},()=>effective(sample(rA),aa));const dataB=Array.from({length:samples},()=>effective(sample(rB,history==='different'?1:0),aa));for(let ep=0;ep<epochs;ep++){for(let i=0;i<samples;i++){const ya=targets(dataA[i]),yb=targets(dataB[i]);if(history==='inverted')yb[0]=2-yb[0];learn(a,dataA[i],ya,.025);learn(b,dataB[i],yb,.025);}progress((ep+1)/epochs);await new Promise(r=>setTimeout(r,0));}return{a,b,seed,history,epochs,samples};}
function hand(x){return[Math.tanh(1.5*x[0]+.2*x[12]+.15*x[13]),Math.tanh(.8*x[5]+.4*x[8]),Math.tanh(x[6]*x[7]),Math.tanh(x[9]+.2*x[8]),Math.tanh(x[10]+.3*x[11]),Math.tanh(.7*x[12]+.4*x[14]),Math.tanh(.7*x[13]+.6*x[15]),Math.tanh(.7*x[14]+.3*x[11])];}
function evaluate(raw,a,net,domain=0,ablate=[]){const x=effective(raw,a,ablate);let h,p;if(net){({h,p}=forward(net,x));if(a.invert){h=h.slice();h[0]*=-1;const read=h.slice();if(a.compensate)read[0]*=-1;p=probs(net.v.map((v,k)=>dot(v,read)+net.c[k]));}}else{h=hand(x);if(a.invert)h[0]*=-1;const read=h.slice();if(a.invert&&a.compensate)read[0]*=-1;const values=[read[0],x[7]<.12?0:read[2]*3,read[3],read[4],x[11]],logits=[];values.forEach(v=>logits.push(-5*v,1.2-2*Math.abs(v),5*v));const val=.5*read[7]+.3*read[6]+.2*read[5];logits.push(-4*val,4*val);p=probs(logits);}const q=p[domain].slice();if(a.labels)[q[0],q[2]]=[q[2],q[0]];const idx=q.indexOf(Math.max(...q));return{x,h,prob:q,report:labels[domain][idx],action:p[5][1]>=.5?'approach':'avoid',actionProbability:p[5][1],confidence:q[idx]};}
function compare(a,b){return{distance:rms(a.h,b.h),cosine:dot(a.h,b.h)/(Math.hypot(...a.h)*Math.hypot(...b.h)||1),same:a.report===b.report&&a.action===b.action,probabilityGap:Math.max(...a.prob.map((v,i)=>Math.abs(v-b.prob[i])),Math.abs(a.actionProbability-b.actionProbability))};}
function solve(A,b){A=A.map((r,i)=>[...r,b[i]]);for(let k=0;k<b.length;k++){let p=k;for(let i=k+1;i<b.length;i++)if(Math.abs(A[i][k])>Math.abs(A[p][k]))p=i;[A[k],A[p]]=[A[p],A[k]];const div=A[k][k];if(Math.abs(div)<1e-12)throw Error('Degenerate alignment');for(let j=k;j<=b.length;j++)A[k][j]/=div;for(let i=0;i<b.length;i++)if(i!==k){const v=A[i][k];for(let j=k;j<=b.length;j++)A[i][j]-=v*A[k][j];}}return A.map(r=>r[b.length]);}
function alignFit(A,B){const X=B.map(h=>[...h,1]),gram=Array.from({length:9},(_,j)=>Array.from({length:9},(_,k)=>X.reduce((s,x)=>s+x[j]*x[k],0)+(j===k?1e-5:0)));return Array.from({length:8},(_,q)=>solve(gram,Array.from({length:9},(_,j)=>X.reduce((s,x,i)=>s+x[j]*A[i][q],0))));}
const aligned=(h,map)=>map.map(w=>dot(w,[...h,1]));
function alignment(pair,agents,seed,domain){const r=rng(seed+331),get=()=>{const raw=sample(r);return[evaluate(raw,agents[0],pair?.a,domain),evaluate(raw,agents[1],pair?.b,domain)];},train=Array.from({length:192},get),map=alignFit(train.map(p=>p[0].h),train.map(p=>p[1].h)),test=Array.from({length:192},get);return{map,calibration:192,heldout:192,raw:Math.sqrt(test.reduce((s,[a,b])=>s+rms(a.h,b.h)**2,0)/test.length),aligned:Math.sqrt(test.reduce((s,[a,b])=>s+rms(a.h,aligned(b.h,map))**2,0)/test.length),agreement:test.filter(([a,b])=>compare(a,b).same).length/test.length};}
const api={fields,groups,labels,rng,clamp,zeros,dot,rms,clone,base,agent,effective,targets,sample,makeNet,forward,trainPair,evaluate,compare,alignment,aligned};
if(typeof module!=='undefined')module.exports=api;root.Qualia=api;
})(typeof globalThis!=='undefined'?globalThis:this);
